import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 4 · Product provenance","description":"","frontmatter":{},"headers":[],"relativePath":"modules/04-product-provenance.md","filePath":"modules/04-product-provenance.md","lastUpdated":1790431304000}'),n={name:"modules/04-product-provenance.md"};function r(o,e,h,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="module-4-·-product-provenance" tabindex="-1">Module 4 · Product provenance <a class="header-anchor" href="#module-4-·-product-provenance" aria-label="Permalink to &quot;Module 4 · Product provenance&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>ProductRegistry.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Market</td></tr><tr><td><strong>Standard</strong></td><td>None — a registry with a custody chain</td></tr><tr><td><strong>Stamp</strong></td><td>Module 4</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>A jar of honey says &quot;Miller Farm&quot; on the label. The label is a sticker. Anyone can print one.</p><p>Supply chains run on documents that assert origin and custody, and the documents are produced by whoever benefits from them. This is the problem that gets blockchains sold to industry more than any other — usually with more confidence than it deserves.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>Record the product&#39;s creation and every change of custody on chain, so the <em>chain of claims</em> is public, timestamped and append-only. Nobody can quietly insert a step, backdate a handover, or remove an inconvenient holder.</p><p>What you get is a record that cannot be edited afterwards. What you do not get is any assurance that the record was true when it was written. Keeping those two apart is the entire point of this module.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Provenance.</strong> The documented history of an object: where it came from, who held it, in what order.</p><p><strong>Custody chain.</strong> The sequence of holders. Each transfer is a transaction signed by the current holder, so the chain is a series of signed claims rather than one party&#39;s ledger.</p><p><strong>Append-only.</strong> Entries are added, never changed or removed. The chain gives this for free; achieving it in a database takes deliberate work and a trusted operator.</p><p><strong>The oracle problem (early sighting).</strong> The gap between a physical fact and what a contract knows. Module 14 confronts this directly; here it appears in a quieter form, and most real-world supply chain projects fail exactly here.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Product</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> creator;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// who registered it</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> holder;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// who has it now</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> createdAt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> transfers;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// how many times it </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">changed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> hands</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> name;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> origin;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docHash;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// certificate, lab report, whatever</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>register(name, origin, docHash)</code></td><td>any resident</td><td>Creates the record, caller becomes holder</td></tr><tr><td><code>transferCustody(id, to, note)</code></td><td>the current holder</td><td>Hands it on, with a public note</td></tr><tr><td><code>get(id)</code></td><td>anyone</td><td>The current record</td></tr><tr><td><code>count()</code></td><td>anyone</td><td>How many products exist</td></tr></tbody></table><p>Only the current holder can transfer, enforced by <code>NotTheHolder(holder)</code> — a custom error that tells you <em>who</em> the holder actually is, which is far more useful when debugging than a bare revert.</p><p>Transferring to yourself reverts with <code>SameHolder()</code>. Small, but it stops a holder padding the custody chain to look busier.</p><p><strong>The history lives in events</strong>, not storage:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">event</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CustodyTransferred</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> note</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Storage keeps only the <em>current</em> holder; the full history is reconstructed from logs. This is a deliberate and very common trade: events cost roughly an order of magnitude less gas than storage, and anything a contract does not need to <em>read</em> should be an event.</p><p>The consequence is that history is only available to something that can query logs — which is why module 2 of the labs has you build exactly that, and why real dApps run indexers.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><code>register</code> takes a <code>docHash</code> and a free-text <code>origin</code>. <strong>The contract checks neither.</strong></p><p>Nothing stops someone registering &quot;Highland Spring Water, origin: Highland Spring&quot; for a bottle filled from a tap. The chain will faithfully record that claim, timestamp it, and preserve it for ever — which makes the lie permanent and attributable, but does not make it false on chain.</p><p>So what has actually been gained?</p><ul><li>The claim is <strong>attributable</strong>: a specific address made it.</li><li>It is <strong>timestamped</strong>: it cannot be backdated.</li><li>It is <strong>immutable</strong>: it cannot be quietly revised when questions are asked.</li><li>The custody chain is <strong>complete</strong>: no step can be hidden.</li></ul><p>That is genuinely useful in a dispute. It is not the same as knowing what is in the jar, and any supply-chain pitch that blurs the two is selling something.</p><p>The honest framing: a blockchain moves the trust problem from <em>many parties who can each rewrite their own records</em> to <em>many parties who must each sign their claims in public</em>. It does not remove it.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Register a product in the Market.</li><li>Transfer custody to a classmate with a note.</li><li>Have them transfer it back.</li><li>On the explorer, filter the contract&#39;s logs for <code>CustodyTransferred</code> with your product id. That is the provenance.</li><li>Try to transfer a product you do not hold. <code>NotTheHolder</code> tells you who does.</li><li>Register a product with an obviously false origin. Nothing stops you. Sit with that.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ProductRegistered(id: 7, creator: 0x…, name: &quot;Jar of honey&quot;, origin: &quot;Miller Farm&quot;, docHash: 0x…)</span></span>
<span class="line"><span>CustodyTransferred(id: 7, from: 0x…, to: 0x…, note: &quot;sold at market&quot;)</span></span></code></pre></div><p><code>id</code> is <code>indexed</code>, so a client can ask for exactly this product&#39;s history without downloading every log the contract ever emitted. Choosing which parameters to index is a design decision: up to three per event, each one a filter someone can use later.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>Within one company, always. A single manufacturer tracking its own inventory does not need consensus with itself, and a database is faster, private and correctable.</p><p>The case appears when <strong>several parties who do not fully trust each other</strong> need one shared record: a farm, a shipper, a processor, a retailer, a regulator. Nobody wants to host the database everyone else depends on, and nobody wants to trust someone else&#39;s.</p><p>Even then, ask the hard question first: is a shared database with signed entries and an audit log sufficient? It usually is, it is far cheaper, and &quot;blockchain&quot; is often the answer to a governance problem that a contract cannot actually solve.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>The input.</strong> Someone typed the origin. A camera, a scale, a lab test — none of those are on chain either.</li><li><strong>The physical link.</strong> A QR code on a jar can be photographed and printed onto another jar. Tying atoms to bytes needs tamper-evident hardware, and that is its own field.</li><li><strong>Collusion.</strong> If every party in the chain agrees to lie, the record is consistent and wrong.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Storing history in an array.</strong> Feels natural, costs a fortune, and grows unbounded. Events exist for this.</li><li><strong>Unbounded strings.</strong> A 10 KB <code>origin</code> costs real money and someone will try it.</li><li><strong>Believing the record.</strong> The most common error, and it is conceptual rather than technical.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can anyone but the holder transfer custody?</li><li>[ ] Can a product be transferred to the zero address, stranding it?</li><li>[ ] Is the history complete from events alone, or does it depend on storage that changed?</li><li>[ ] What stops an address registering ten thousand products?</li><li>[ ] If the same <code>docHash</code> is registered twice, what does that mean? Should it be allowed?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Require a <em>receiving</em> signature — custody transfers only when the recipient accepts. Two transactions instead of one; say what that prevents.</li><li>Add batch and sub-batch relationships (a pallet holds cases, a case holds jars), and discover why GS1&#39;s EPCIS standard has aggregation events.</li><li>Restrict transfers to registered residents, and argue about whether that helps or just moves the problem.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://www.gs1.org/standards/epcis" target="_blank" rel="noreferrer">GS1 EPCIS 2.0</a> — the industry event model for exactly this, worth seeing before you invent your own schema.</li><li><a href="https://docs.soliditylang.org/en/latest/contracts.html#events" target="_blank" rel="noreferrer">Solidity events and logs</a></li></ul><p><strong>Next:</strong> <a href="./05-escrow">Module 5 · Escrow →</a></p>`,49)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
